SELECT ?s ?o WHERE {
  ?s brick:hasSubclass* ?z .
  FILTER(str(?s) LIKE "%Zone_F3%" || str(?s) LIKE "%F3_Z01%")
  OPTIONAL { ?s rdfs:label ?lbl }
  OPTIONAL { ?s a ?cls }
}

SELECT ?s WHERE {
  ?s a brick:Zone_Temperature_Sensor .
  OPTIONAL { ?s rdfs:label ?l }
}

SELECT ?s ?cls ?l WHERE {
  ?s a ?cls .
  FILTER(str(?s) LIKE "%F3_Z01%" || str(?s) LIKE "%Zone_F3%" || str(?s) LIKE "%Core%")
  OPTIONAL { ?s rdfs:label ?l }
}

SELECT ?s ?cls ?l {
  ?s a ?cls .
  OPTIONAL { ?s rdfs:label ?l } .
  FILTER(str(?s) LIKE "%F3_Z01%")
}

